package com.supportsphere.controller; import com.supportsphere.model.*; import com.supportsphere.service.*; import com.supportsphere.util.*; import javafx.fxml.*; import javafx.scene.control.*; import java.time.*;
public class CreateRequestController { @FXML ComboBox<String> task,urgency; @FXML TextArea description; @FXML TextField area,city,landmark; @FXML DatePicker date; @FXML TextField start,end; private final RequestService service=new RequestService(); @FXML void initialize(){task.getItems().addAll("Medicine Collection","Grocery Shopping","Transportation","Bill Payment","Appointment Assistance","Document Assistance","Household Assistance","Other");urgency.getItems().addAll("LOW","MEDIUM","HIGH","EMERGENCY");task.getSelectionModel().selectFirst();urgency.getSelectionModel().select("MEDIUM");date.setValue(LocalDate.now());User u=Session.getUser();area.setText(u.getArea());city.setText(u.getCity());landmark.setText(u.getLandmark());} @FXML void save(){try{AssistanceRequest r=new AssistanceRequest();r.setRequesterId(Session.getUser().getUserId());r.setTaskType(task.getValue());r.setDescription(description.getText());r.setArea(area.getText());r.setCity(city.getText());r.setLandmark(landmark.getText());r.setUrgency(Urgency.valueOf(urgency.getValue()));r.setPreferredDate(date.getValue());r.setStartTime(LocalTime.parse(start.getText()));r.setEndTime(LocalTime.parse(end.getText()));int id=service.create(r);Dialogs.info("Request created","Request #"+id+" is now open. Suitable volunteers will see it in their recommendations.");SceneManager.show("requester-dashboard.fxml","SupportSphere — Requester");}catch(Exception e){Dialogs.error("Could not create request",e.getMessage());}} @FXML void back(){try{SceneManager.show("requester-dashboard.fxml","SupportSphere — Requester");}catch(Exception e){}} }
